import{_ as e,o,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const b=JSON.parse('{"title":"AiBubbleContent（内部件 · 仅 API）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agent/src/components/bubble/docs/README-AiBubbleContent.md","filePath":"docs/agent/src/components/bubble/docs/README-AiBubbleContent.md"}'),c={name:"docs/agent/src/components/bubble/docs/README-AiBubbleContent.md"};function r(i,t,n,s,l,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="aibubblecontent-内部件-·-仅-api" tabindex="-1">AiBubbleContent（内部件 · 仅 API） <a class="header-anchor" href="#aibubblecontent-内部件-·-仅-api" aria-label="Permalink to &quot;AiBubbleContent（内部件 · 仅 API）&quot;">​</a></h1><blockquote><p>内部件，[MUST NOT] 当公共组件用。气泡内容渲染：AI 角色 = 推理轨脊柱（流式 shimmer）+ 打字机 + 思考折叠 + XMarkdown；用户角色 = 纯文本（无 markdown）。两种角色<strong>共用同一条 parts 渲染链</strong>（<code>#part</code> / <code>#tool</code> 转发口 + <code>AiPartRenderer</code> 兜底）——用户侧的 parts 来自 <code>ask({ parts })</code>。AiDialogue / AiMessageList 的 <code>#content</code> 渲染核心。</p></blockquote><h2 id="窄容器可读性-0-3-0" tabindex="-1">窄容器可读性（0.3.0） <a class="header-anchor" href="#窄容器可读性-0-3-0" aria-label="Permalink to &quot;窄容器可读性（0.3.0）&quot;">​</a></h2><p>侧栏内嵌（约 300px）时 AI 正文的实际可用宽只剩百余像素，本组件对 XMarkdown 输出做了四处修正——都是几何 / 可达性，不是视觉定制：</p><table tabindex="0"><thead><tr><th>#</th><th>修正</th><th>原状</th></tr></thead><tbody><tr><td>ⓐ</td><td><strong>代码块横向可达</strong>：滚动容器上移到 <code>.pre-md</code> + <code>code</code> 撑到 <code>max-content</code>，语言标签栏 <code>sticky left:0</code> 钉住</td><td><code>code</code> 虽标 <code>overflow-x:auto</code> 但 <code>scrollWidth</code> 恒等于 <code>clientWidth</code>——超出的行<strong>既看不见也滚不到</strong>（实测 300px 下右侧 117px 永久丢失）</td></tr><tr><td>ⓑ</td><td><strong>行内 code 不逐字符劈开</strong>：<code>word-break: normal</code> + <code>overflow-wrap: break-word</code></td><td>第三方设 <code>break-all</code>，<code>greet(name)</code> 被断成 <code>gre</code> / <code>et(name)</code></td></tr><tr><td>ⓒ</td><td><strong>列表缩进归一</strong> <code>1.5em</code></td><td>浏览器默认 <code>40px</code>，在 300px 面板里吃掉 20% 横向空间</td></tr><tr><td>ⓓ</td><td><strong>窄容器脊柱缩进降档</strong>（<code>@container dc-agent (max-width:360px)</code> → <code>space-2</code>）</td><td>恒 <code>space-4</code>(16px)</td></tr></tbody></table><blockquote><p>容器上下文由 <code>.ai-dialogue</code>（自管路径）与 <code>.ai-message-list</code>（受控路径）<strong>同名建立</strong>（<code>container-name: dc-agent</code>），两条路径行为一致。</p></blockquote><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ 以组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>item</code></td><td><code>XBubbleListItemProps</code>（必填）</td><td>—</td><td>内部气泡项（content / role / isFinished / showThink / typing 等）</td></tr><tr><td><code>codeXSlot</code></td><td><code>CodeBlockHeaderExpose</code>（必填）</td><td>—</td><td>代码块头部控制（useCodeXSlot 产物）</td></tr><tr><td><code>typingMsgUuid</code></td><td><code>string?</code></td><td>—</td><td>打字机效果消息 uuid（仅该 uuid 的消息流式打字，其余直接展示）</td></tr><tr><td><code>allowHtml</code></td><td><code>boolean?</code></td><td><code>true</code></td><td>markdown 允许内联 HTML（透传 XMarkdown）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>参数</th><th>语义</th></tr></thead><tbody><tr><td><code>typingFinished</code></td><td><code>uuid: string</code></td><td>打字机完成（AiDialogue 据此推进 typingMsgCtrl）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>part</code></td><td><code>{ part: AiDataPart, item: XBubbleListItemProps }</code></td><td>业务 <code>data-*</code> part 渲染口；缺省退回 <code>AiPartRenderer</code></td></tr><tr><td><code>tool</code></td><td><code>{ part: AiToolPart, item: XBubbleListItemProps }</code></td><td>工具调用 part 渲染口；缺省退回 <code>AiPartRenderer</code></td></tr></tbody></table><p>两槽由 <code>AiDialogue</code> 以 <code>v-if=&quot;$slots.x&quot;</code> 守卫转发（无条件转发会用空 <code>&lt;slot&gt;</code> 遮蔽掉默认内容）。</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="机制契约" tabindex="-1">机制契约 <a class="header-anchor" href="#机制契约" aria-label="Permalink to &quot;机制契约&quot;">​</a></h2><ul><li>打字机开关：<code>item.typing</code>（默认 true）→ 当前消息为 typingMsgUuid 时逐字、否则直接全文；<code>item.typing === false</code> 全局禁用</li><li><code>customAttrs.think</code>：<code>&lt;think&gt;</code> 标签自定义渲染（div + break-all）</li><li><strong>parts 渲染链两角色共用</strong>：<code>data-*</code> → <code>#part</code>、<code>tool-call</code> → <code>#tool</code>、其余（reasoning / file）→ <code>AiPartRenderer</code>。用户气泡的 parts 由 <code>ask({ parts })</code> 写入；<code>item.parts</code> 为空时该段不产出任何节点</li><li><strong>时序交错（q21yfk 判据 1 · 方案 B）</strong>：<code>item.partOffsets</code>（与 <code>parts</code> 平行的正文偏移数组，sse 层记录）存在时，正文按偏移切段、parts 插在对应切点——重演 agent 真实工作时序（正文₁ → 工具卡 → 正文₂）；打字机推进越过偏移点时 part 才浮现（<code>textShow.length &gt;= offset</code>）。<strong>切点保护</strong>：偏移落在未闭合 <code>&lt;think&gt;</code> 块内时顺延到 <code>&lt;/think&gt;</code> 后。<code>partOffsets</code> 缺省（存量历史消息）→ 退回旧序（正文后挂 parts），零回归</li><li>错误信息（<code>item.errorMsg</code>）在内容下方红色渐变展示；用户角色无错误场景</li><li>markdown 透传 props：<code>allowHtml</code> + codeXSlot（代码块复制/折叠经 <code>AiCodeHeaderControl</code>）</li></ul>',19)])])}const u=e(c,[["render",r]]);export{b as __pageData,u as default};
